// 1. Capturar datos del nodo de entrada con valores por defecto
const inputJson = $input.first()?.json || {};

// 2. Extraer y formatear la Cotización del Dólar PTAX (a 4 decimales)
let dolarRaw = inputJson.cotizacion_ptax 
  || inputJson.dolar;

// Si no viene en el input directo, busca en el nodo de la cotización
try {
  if (!dolarRaw && typeof $('Cotizacion Dolar BCB') !== 'undefined') {
    const bcbJson = $('Cotizacion Dolar BCB').first()?.json;
    // Extrae de AwesomeAPI (USDBRL.bid) o del formato antiguo BCB
    dolarRaw = bcbJson?.USDBRL?.bid || bcbJson?.value?.[0]?.cotacaoVenda;
  }
} catch (e) {
  // Ignora si el nodo no existe en la ejecución actual
}

// Si sigue sin encontrarse, intenta extraerlo del texto generado por la IA
if (!dolarRaw && inputJson.text) {
  const matchDolar = inputJson.text.match(/R\$\s*([\d[.,]+)/i);
  if (matchDolar) {
    dolarRaw = matchDolar[1].replace(',', '.');
  }
}

const dolarNum = parseFloat(dolarRaw);
const dolar = !isNaN(dolarNum) ? dolarNum.toFixed(4).replace('.', ',') : '4,9935';

// 3. Extraer y formatear el Clima
let tempRaw = inputJson.temperatura;
let condRaw = inputJson.condicion_clima;

try {
  if (!tempRaw && typeof $('Clima Cascavel') !== 'undefined') {
    tempRaw = $('Clima Cascavel').first()?.json?.main?.temp;
    condRaw = $('Clima Cascavel').first()?.json?.weather?.[0]?.description;
  }
} catch (e) {
  // Ignora si el nodo no existe en la ejecución actual
}

const tempNum = parseFloat(tempRaw);
const clima = !isNaN(tempNum) ? Math.round(tempNum) : '20';
const condicion = condRaw || 'chuva leve';

// 4. Extraer y limpiar el Titular de la Noticia desde el texto de la IA
let textoIA = '';
try {
  if (typeof $('Instagram Mensaje') !== 'undefined') {
    textoIA = $('Instagram Mensaje').first()?.json?.text || '';
  }
} catch (e) {
  // Ignora si el nodo no existe
}

if (!textoIA && inputJson.text) {
  textoIA = inputJson.text;
}

let primerRenglon = textoIA.split('\n').find(linea => linea.trim().length > 0) || '';
primerRenglon = primerRenglon.replace(/[*#]/g, '').trim();

const titulo = inputJson.resumen_noticia 
  || (primerRenglon.length > 5 ? primerRenglon : null)
  || 'Dólar PTAX e Clima: Tudo sobre o Agro hoje!';

// 5. Imagen de Fondo Dinámica
let palabraClave = inputJson.keyword || '';

if (!palabraClave) {
  const tituloMin = titulo.toLowerCase();
  if (tituloMin.includes('laranja') || tituloMin.includes('suco') || tituloMin.includes('citros')) palabraClave = 'citrus';
  else if (tituloMin.includes('soja')) palabraClave = 'soybean';
  else if (tituloMin.includes('milho')) palabraClave = 'cornfield';
  else if (tituloMin.includes('boi') || tituloMin.includes('carne') || tituloMin.includes('gado')) palabraClave = 'cattle';
  else if (tituloMin.includes('trator') || tituloMin.includes('maquina')) palabraClave = 'tractor';
  else if (tituloMin.includes('café')) palabraClave = 'coffee';
  else palabraClave = 'agriculture';
}

// URL de Picsum combinando el tema de la noticia con una variación aleatoria por ejecución
const fotoFondo = inputJson.imagen_gemini_url 
  || `https://picsum.photos/seed/${encodeURIComponent(palabraClave + Date.now())}/1080/1080`;

const logoUrl = 'https://i.ibb.co/h1HcGsfX/agrotech-logo.jpg'; 
