  }

  /* Contenido */
  .container {
    position: relative; z-index: 10; width: 1080px; height: 1080px;
    padding: 60px; display: flex; flex-direction: column; justify-content: space-between;
  }

  /* Header */
  .header {
    background: #FFFFFF; border-radius: 20px; padding: 20px 40px;
    display: flex; justify-content: space-between; align-items: center;
    box-shadow: 0 10px 25px rgba(0,0,0,0.2);
  }
  .logo { height: 80px; object-fit: contain; }
  .location-badge { color: #22B182; font-weight: 700; font-size: 22px; }

